import java.util.PriorityQueue;
import java.util.Comparator;

class HuffmanNode {
    char ch;
    int freq;
    HuffmanNode left, right;

    HuffmanNode(char ch, int freq) {
        this.ch = ch;
        this.freq = freq;
    }
}

public class Huffman {
    public static HuffmanNode buildHuffmanTree(
            char[] chars, int[] freqs) {
        PriorityQueue<HuffmanNode> minHeap = 
            new PriorityQueue<>((a, b) -> a.freq - b.freq);

        // Insert all characters into min heap
        for (int i = 0; i < chars.length; i++) {
            minHeap.offer(new HuffmanNode(chars[i], freqs[i]));
        }

        // Build tree
        while (minHeap.size() > 1) {
            HuffmanNode left = minHeap.poll();
            HuffmanNode right = minHeap.poll();

            HuffmanNode parent = new HuffmanNode('\0', 
                left.freq + right.freq);
            parent.left = left;
            parent.right = right;
            minHeap.offer(parent);
        }

        return minHeap.poll();
    }
}
